# Mathematics, trigonometry, coordinate geometry, vectors and 3D geometry
# (10+2 CBSE), including heights and distances.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 1, "Trigonometry", r"What is the value of $\cos 45^\circ \cos 15^\circ - \sin 45^\circ \sin 15^\circ$?",
      [r"$\frac{1}{2}$", r"$\frac{\sqrt{3}}{2}$", r"$\frac{1}{\sqrt{2}}$", r"$1$"],
      r"$\cos A \cos B - \sin A \sin B = \cos(A + B)$, so the value is $\cos 60^\circ = \frac{1}{2}$. $\frac{\sqrt{3}}{2}$ is $\cos 30^\circ$, the result of using $A - B$."),
    S(1, 1, "Trigonometry", r"What is $150^\circ$ in radians?",
      [r"$\frac{5\pi}{6}$", r"$\frac{3\pi}{4}$", r"$\frac{2\pi}{3}$", r"$\frac{5\pi}{3}$"],
      r"Multiply by $\frac{\pi}{180}$: $150 \times \frac{\pi}{180} = \frac{5\pi}{6}$. $\frac{2\pi}{3}$ is $120^\circ$ and $\frac{3\pi}{4}$ is $135^\circ$."),
    S(1, 2, "Heights and distances", r"From a point on level ground 40 m from the foot of a tower, the angle of elevation of its top is $60^\circ$. How tall is the tower?",
      [r"$40\sqrt{3}$ m", r"$\frac{40}{\sqrt{3}}$ m", r"$20$ m", r"$80$ m"],
      r"$\tan 60^\circ = h / 40$, so $h = 40\sqrt{3}$ m (about 69 m). $\frac{40}{\sqrt{3}}$ m uses $\tan 30^\circ$, 20 m multiplies by $\cos 60^\circ$, and 80 m is the length of the line of sight ($40 \div \cos 60^\circ$), not the height."),
    S(1, 1, "Coordinate geometry", "What is the distance between the points (1, -1) and (6, 11)?",
      ["13", "17", "169", "12"],
      r"$d = \sqrt{(6-1)^2 + (11-(-1))^2} = \sqrt{25 + 144} = 13$. 169 forgets the square root, 17 adds the differences 5 and 12, and 12 is the vertical difference alone."),
    S(1, 2, "Coordinate geometry", "What is the slope of the line 4x - 7y + 14 = 0?",
      ["4/7", "-4/7", "7/4", "2"],
      r"Rewrite as $y = \frac{4}{7}x + 2$, so the slope is $\frac{4}{7}$ (for $ax + by + c = 0$ the slope is $-a/b = -4/(-7)$). 2 is the y-intercept, $-\frac{4}{7}$ drops the sign of b, and $\frac{7}{4}$ inverts the fraction."),
    S(1, 2, "Coordinate geometry", r"What is the radius of the circle $x^2 + y^2 + 4x - 10y - 7 = 0$?",
      ["6", "36", r"$\sqrt{22}$", "7"],
      r"Complete the squares: $(x + 2)^2 + (y - 5)^2 = 7 + 4 + 25 = 36$. The centre is (-2, 5) and the radius is $\sqrt{36} = 6$. 36 is $r^2$, and $\sqrt{22}$ subtracts the 7 instead of adding it."),
    S(1, 1, "Vectors", r"What is the dot product of $\vec{a} = 2\hat{i} + 3\hat{j}$ and $\vec{b} = 4\hat{i} - \hat{j}$?",
      ["5", "11", "7", "8"],
      r"$\vec{a} \cdot \vec{b} = (2)(4) + (3)(-1) = 8 - 3 = 5$. 11 ignores the minus sign on the $\hat{j}$ part of $\vec{b}$, and 8 uses only the $\hat{i}$ parts."),
    S(1, 1, "Three-dimensional geometry", "How far is the point (4, 4, 7) from the origin?",
      ["9", "15", "7", "81"],
      r"$d = \sqrt{4^2 + 4^2 + 7^2} = \sqrt{16 + 16 + 49} = \sqrt{81} = 9$. 15 adds the coordinates, 81 forgets the square root, and 7 is the largest coordinate alone."),

    # ---------- Practice Test 2 ----------
    S(2, 1, "Trigonometry", r"If $\cos \theta = \frac{9}{41}$ and $\theta$ is acute, what is $\tan \theta$?",
      ["40/9", "9/40", "40/41", "41/40"],
      r"With adjacent side 9 and hypotenuse 41, the opposite side is $\sqrt{1681 - 81} = \sqrt{1600} = 40$. So $\tan \theta = 40/9$. 9/40 is $\cot \theta$, 40/41 is $\sin \theta$ and 41/40 is $\csc \theta$."),
    S(2, 2, "Trigonometry", r"What is the period of the function $\sin \frac{x}{2}$?",
      [r"$4\pi$", r"$\pi$", r"$2\pi$", r"$\frac{\pi}{2}$"],
      r"$\sin x$ has period $2\pi$. For $\sin kx$ the period is $2\pi / k$; here $k = \frac{1}{2}$, so the period is $2\pi \div \frac{1}{2} = 4\pi$. Halving x stretches the graph, so the period gets longer, not shorter."),
    S(2, 1, "Heights and distances", r"A 10 m ladder leans against a wall and makes an angle of $60^\circ$ with the ground. How far is its foot from the wall?",
      ["5 m", "8.66 m", "10 m", "20 m"],
      r"Distance from the wall = $10 \cos 60^\circ = 10 \times \frac{1}{2} = 5$ m. 8.66 m is $10 \sin 60^\circ$, the height the ladder reaches up the wall, and 20 m divides by $\cos 60^\circ$ instead of multiplying."),
    S(2, 1, "Coordinate geometry", "What is the midpoint of the line segment joining (2, -4) and (6, 8)?",
      ["(4, 2)", "(4, 6)", "(8, 4)", "(2, 6)"],
      "Midpoint = ((2 + 6)/2, (-4 + 8)/2) = (4, 2). (8, 4) adds the coordinates without halving them."),
    S(2, 1, "Coordinate geometry", "What is the equation of the line with slope -2 that crosses the y-axis at (0, 5)?",
      ["y = -2x + 5", "y = 5x - 2", "y = -2x - 5", "y = 2x + 5"],
      "The slope-intercept form is y = mx + c, with m = -2 and c = 5 (the y-intercept). So y = -2x + 5. y = 5x - 2 swaps the slope and the intercept."),
    S(2, 2, "Conic sections", r"What is the focus of the parabola $x^2 = 16y$?",
      ["(0, 4)", "(4, 0)", "(0, 16)", "(0, 8)"],
      r"Compare with $x^2 = 4ay$, a parabola opening upward: $4a = 16$, so $a = 4$ and the focus is $(0, a) = (0, 4)$. (4, 0) puts it on the wrong axis, and (0, 16) uses 4a instead of a."),
    S(2, 1, "Vectors", r"What is the magnitude of the vector $2\hat{i} - \hat{j} + 2\hat{k}$?",
      ["3", "9", "5", "1"],
      r"$|\vec{v}| = \sqrt{2^2 + (-1)^2 + 2^2} = \sqrt{9} = 3$. 9 forgets the square root."),
    S(2, 2, "Vectors", r"For what value of $\lambda$ are the vectors $2\hat{i} + \lambda\hat{j} + \hat{k}$ and $\hat{i} - 2\hat{j} + 4\hat{k}$ perpendicular?",
      ["3", "-3", "2", "6"],
      r"Perpendicular vectors have a zero dot product: $2(1) + \lambda(-2) + 1(4) = 0$, so $6 - 2\lambda = 0$ and $\lambda = 3$."),

    # ---------- Drill only ----------
    S(0, 2, "Trigonometry", r"What is the exact value of $\tan 15^\circ$?",
      [r"$2 - \sqrt{3}$", r"$2 + \sqrt{3}$", r"$\sqrt{3} - 1$", r"$\frac{1}{\sqrt{3}}$"],
      r"$\tan(45^\circ - 30^\circ) = \frac{1 - \frac{1}{\sqrt{3}}}{1 + \frac{1}{\sqrt{3}}} = \frac{\sqrt{3} - 1}{\sqrt{3} + 1} = 2 - \sqrt{3}$ (about 0.268). $2 + \sqrt{3}$ is $\tan 75^\circ$."),
    S(0, 2, "Trigonometry", r"If $\sec \theta + \tan \theta = 2$, what is $\sec \theta - \tan \theta$?",
      ["1/2", "2", "-2", "1/4"],
      r"$\sec^2 \theta - \tan^2 \theta = 1$, so $(\sec \theta + \tan \theta)(\sec \theta - \tan \theta) = 1$. Hence $\sec \theta - \tan \theta = 1/2$."),
    S(0, 1, "Coordinate geometry", "What is the area of the triangle with vertices (0, 0), (6, 0) and (0, 8)?",
      ["24", "48", "14", "10"],
      "It is a right triangle with legs 6 and 8 along the axes, so its area is ½ x 6 x 8 = 24 square units. 48 leaves out the ½, 14 adds the legs, and 10 is the length of the third side."),
    S(0, 2, "Coordinate geometry", "What point divides the segment joining (2, 1) and (8, 10) internally in the ratio 1 : 2?",
      ["(4, 4)", "(6, 7)", "(5, 5.5)", "(2, 3)"],
      "Section formula: ((1 x 8 + 2 x 2)/3, (1 x 10 + 2 x 1)/3) = (12/3, 12/3) = (4, 4). (6, 7) divides it in the ratio 2 : 1, and (5, 5.5) is the midpoint."),
    S(0, 1, "Conic sections", "What is the eccentricity of a circle?",
      ["0", "1", "Between 0 and 1", "Greater than 1"],
      "A circle is an ellipse whose two foci coincide at the centre, so its eccentricity is 0. A parabola has e = 1, an ellipse 0 < e < 1 and a hyperbola e > 1."),
    S(0, 1, "Vectors", r"What is $\hat{i} \times \hat{j}$?",
      [r"$\hat{k}$", r"$-\hat{k}$", r"$0$", r"$1$"],
      r"For the right-handed unit vectors, $\hat{i} \times \hat{j} = \hat{k}$, while $\hat{j} \times \hat{i} = -\hat{k}$. The cross product of two vectors is a vector, so 0 and 1 (scalars) cannot be right."),
    S(0, 2, "Three-dimensional geometry", "If l, m and n are the direction cosines of a line, then",
      [r"$l^2 + m^2 + n^2 = 1$", r"$l + m + n = 1$", r"$l^2 + m^2 + n^2 = 0$", r"$lmn = 1$"],
      r"Direction cosines are $\cos \alpha, \cos \beta, \cos \gamma$ of the angles a line makes with the axes, and the squares of these always add up to 1."),
    S(0, 1, "Trigonometry", r"What is the value of $\cos^2 30^\circ - \sin^2 30^\circ$?",
      [r"$\frac{1}{2}$", r"$\frac{\sqrt{3}}{2}$", r"$1$", r"$0$"],
      r"$\cos^2 \theta - \sin^2 \theta = \cos 2\theta$, so the value is $\cos 60^\circ = \frac{1}{2}$. Check: $\frac{3}{4} - \frac{1}{4} = \frac{1}{2}$. 1 is $\cos^2 \theta + \sin^2 \theta$."),
]
